"""Diverse active annotation ranking from independent uncertainty signals."""
import math, random

def rank_candidates(candidates, seed=7):
    # Candidate dict signals are independently generated by the caller: uncertainty, novelty,
    # rare_workflow, disagreement, and high_confidence_audit.
    rng=random.Random(seed)
    for x in candidates:
        vals=[max(0,min(1,float(x.get(k,0)))) for k in ("uncertainty","novelty","rare_workflow","disagreement","high_confidence_audit")]
        x["information_score"]=sum((1.0 if i<4 else .18)*v for i,v in enumerate(vals)) + rng.random()*1e-7
    return sorted(candidates,key=lambda x:(-x["information_score"],x.get("session_id","")))

def diverse_select(candidates, limit, similarity=None):
    selected=[]; used=set()
    for x in candidates:
        sid=x.get("session_id")
        if sid in used: continue
        if similarity and any(similarity(x,y)>.88 for y in selected): continue
        selected.append(x); used.add(sid)
        if len(selected)>=limit: break
    return selected

def rank_residual_sessions(sessions, labels, classifier, seed=7):
    """Rank unlabeled sessions for direct review using uncertainty and coverage signals.

    Scores prioritize low-margin model suggestions, novel text, underrepresented
    predicted workflows, and disagreement with a nearest labeled example. These
    scores are ranking aids, not calibrated probabilities.
    """
    from collections import Counter, defaultdict
    import hashlib
    from sklearn.feature_extraction.text import TfidfVectorizer
    from sklearn.metrics.pairwise import cosine_similarity
    from .classifier import HierarchicalClassifier

    if not sessions:
        return []
    training=[x for x in labels if x.get("use_case_id") and x.get("workflow_id")]
    if not training:
        return [{"session":s,"session_id":s["trace_id"],"information_score":0.0} for s in sessions]
    train_text=[HierarchicalClassifier._text(x) for x in training]
    candidate_text=[HierarchicalClassifier._text(x) for x in sessions]
    vectorizer=TfidfVectorizer(ngram_range=(1,2),min_df=1,sublinear_tf=True,max_features=50000)
    matrix=vectorizer.fit_transform(train_text+candidate_text)
    sims=cosine_similarity(matrix[len(training):],matrix[:len(training)])
    train_uc=[x["use_case_id"] for x in training]
    workflow_counts=Counter(x["workflow_id"] for x in training)
    total=max(workflow_counts.values(),default=1)
    ranked=[]
    for i,session in enumerate(sessions):
        pred=classifier.predict_one(session)
        nearest=int(sims[i].argmax())
        gap=max(0.0,float(pred.get("decision_gap") or 0.0))
        # SVM margins are not calibrated; a monotone transform is used only to rank.
        uncertainty=1.0/(1.0+gap)
        novelty=1.0-float(sims[i,nearest])
        wf=pred.get("workflow_id")
        rare=(1.0-(workflow_counts.get(wf,0)/total)) if wf else 1.0
        disagreement=float(train_uc[nearest] != pred.get("use_case_id"))
        audit=int(hashlib.sha256(str(session["trace_id"]).encode()).hexdigest()[:8],16)%10==0
        row={"session":session,"session_id":session["trace_id"],"uncertainty":uncertainty,
             "novelty":novelty,"rare_workflow":rare,"disagreement":disagreement,
             "high_confidence_audit":float(audit),"predicted_use_case_id":pred.get("use_case_id"),
             "predicted_workflow_id":wf,"decision_gap":pred.get("decision_gap")}
        ranked.append(row)
    ranked=rank_candidates(ranked,seed)
    # Round-robin structural archetypes so repeated variants do not consume early GLM batches.
    buckets=defaultdict(list)
    for row in ranked:
        buckets[row["session"].get("archetype_id",row["session_id"])].append(row)
    keys=sorted(buckets)
    ordered=[]
    while keys:
        next_keys=[]
        for key in keys:
            ordered.append(buckets[key].pop(0))
            if buckets[key]: next_keys.append(key)
        keys=next_keys
    return ordered
